from ta_tshark_hex_parser.uesim_parser import UesimParser


def get_hex_parser(source_description=None, stop_condition=None):
    """

    :param source_description:
    :param stop_condition:
    :return:
    """
    if source_description is not None:
        return UesimParser(source_description=source_description, stop_condition=stop_condition)
    else:
        return UesimParser(stop_condition=stop_condition)
